    'auth_favorites_prompt': { 'Русский': 'Чтобы сохранить это объявление в избранное, необходимо войти в свой профиль. Это займет всего пару секунд!', 'Қазақша': 'Бұл хабарландыруды таңдаулыларға сақтау үшін профиліңізге кіруіңіз керек. Бұл бірнеше секундты алады!', 'Уйғурчә': 'Бу еланни талланғанларға сақлаш үчүн тизимлишишиңиз керәк. Бу бир нәччә секунд вақит алиду!' },
    'auth_bargain_prompt': { 'Русский': 'Чтобы предложить свою цену продавцу, необходимо войти в свой профиль. Это займет всего пару секунд!', 'Қазақша': 'Сатушыға өз бағаңызды ұсыну үшін профиліңізге кіруіңіз керек. Бұл бірнеше секундты алады!', 'Уйғурчә': 'Сатқучиға өз баһаңизни сунуш үчүн тизимлишишиңиз керәк. Бу бир нәччә секунд вақит алиду!' },
    'auth_chat_prompt': { 'Русский': 'Чтобы написать продавцу, необходимо войти в свой профиль. Это займет всего пару секунд!', 'Қазақша': 'Сатушыға жазу үшін профиліңізге кіруіңіз керек. Бұл бірнеше секундты алады!', 'Уйғурчә': 'Сатқучиға йезиш үчүн тизимлишишиңиз керәк. Бу бир нәччә секунд вақит алиду!' },
    'auth_call_prompt': { 'Русский': 'Чтобы позвонить продавцу, необходимо войти в свой профиль. Это займет всего пару секунд!', 'Қазақша': 'Сатушыға қоңырау шалу үшін профиліңізге кіруіңіз керек. Бұл бірнеше секундты алады!', 'Уйғурчә': 'Сатқучиға телефон қилиш үчүн тизимлишишиңиз керәк. Бу бир нәччә секунд вақит алиду!' },
    'auth_taxi_order_prompt': { 'Русский': 'Чтобы заказать такси, необходимо войти в свой профиль. Это займет всего пару секунд!', 'Қазақша': 'Таксиге тапсырыс беру үшін профиліңізге кіруіңіз керек. Бұл бірнеше секундты алады!', 'Уйғурчә': 'Такси заказ қилиш үчүн тизимлишишиңиз керәк. Бу бир нәччә секунд вақит алиду!' },
    'auth_taxi_create_prompt': { 'Русский': 'Чтобы предложить поездку пассажирам, необходимо войти в свой профиль. Это займет всего пару секунд!', 'Қазақша': 'Жолаушыларға сапар ұсыну үшін профиліңізге кіруіңіз керек. Бұл бірнеше секундты алады!', 'Уйғурчә': 'Йолучиларға сәпәр сунуш үчүн тизимлишишиңиз керәк. Бу бир нәччә секунд вақит алиду!' },
    'auth_taxi_profile_prompt': { 'Русский': 'Чтобы просмотреть профиль пользователя, необходимо войти в свой профиль. Это займет всего пару секунд!', 'Қазақша': 'Пайдаланушы профилін көру үшін профиліңізге кіруіңіз керек. Бұл бірнеше секундты алады!', 'Уйғурчә': 'Униң профилини көрүш үчүн тизимлишишиңиз керәк. Бу бир нәччә секунд вақит алиду!' },
